function UIBattleEndContinuousFightSummaryDialog:InitComponent()
    self.Txt_DescEndReason.text = tostring(self.parameters.content)
    self.Txt_DescTotalTimes.text = localize("总共连续作战<size=38><color=#FE1CA9> _num_ </color></size>轮", {_num_ = teamComponent:GetCurContinueNum()})
