        UIModule.BackDialog()
    end)
    -- 消耗道具
    self.LB_ConsumeGoodsGroup:Init()
    local LT_ConsumeGoodsGroup = self.LB_ConsumeGoodsGroup.Env
    LT_ConsumeGoodsGroup:ShowConsumeGoods(self:CalculateConsumeGoods())
    -- 奖励
    self:CalculateRewardList()
    self:RefreshRewardsList(#self.rewardList)
    -- 固定奖励
    self:RefreshExtraRewardsList()
