--- 计算消耗道具和可兑换道具使用的数量
function UIBattleEndContinuousFightSummaryDialog:CalculateConsumeGoods()
    local questId = BattleEndMgr.questId
    local curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    local goods = {}

    -- 可兑换道具
    local costId
    local t = CfUtils.GetCf(AutoIds.IdSetting302, "ExchangeStrengthVo", true)
    for k, v in pairs(t) do
        if checkNumber(v.getItemId) == checkNumber(curLevelVo.costItem) then
            costId = checkNumber(v.itemId)
        end
    end
    if isNotNull(costId) then
        local exchangeGoodInfo = {}
        exchangeGoodInfo.id = costId
        exchangeGoodInfo.num = teamComponent:GetExchangeItemCostNum()
        table.insert(goods, exchangeGoodInfo)
    end

    -- 消耗道具
    local consumeItemInfo = {}
    consumeItemInfo.id = checkNumber(curLevelVo.costItem)
    local needNum = (checkNumber(curLevelVo.costNum) + checkNumber(curLevelVo.costNumLose))
    if curLevelVo then
        if checkNumber(curLevelVo.levelType) == Constants.RegionSecondQuestType.Equip then
            ---装备本
            --@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
            local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
            if status == 1 and times > 0  then
                ---@type TableML.TableFile
                local tableFile = settingModule.Get(AutoIds.IdSetting313)
                ---@type TableML.TableFileRow
                local row = tableFile:GetByPrimaryKey(checkNumber(questId), false)
                if row then
                    needNum = checkNumber(row:Get("costNum")) + checkNumber(curLevelVo.costNumLose)
                end
            end
        end
    end
    consumeItemInfo.num = needNum * teamComponent:GetCurContinueNum()
    table.insert(goods, consumeItemInfo)

    return goods
end

function UIBattleEndContinuousFightSummaryDialog:CalculateRewardList()
    local rewardsList = teamComponent:GetContinueFightRewards()
    -- print("[连续作战] 奖励列表", table.dump(rewardsList, nil, 3))
    if table.count(rewardsList) == 0 then
        self.rewardList = {}
        return
    end

    -- 首通奖励
    local firstList = {}
    -- 非首通奖励
    local rewardsDict = {}

    -- 把每次结算的奖励整理到首通列表和非首通列表里
    for i, onceRewards in ipairs(rewardsList) do
        for j, goodsData in ipairs(onceRewards) do
            if checkInt(goodsData.from) == Constants.RewardSourceType.FirstPass then
                table.insert(firstList, {goodsId = checkInt(goodsData.goodsId), num = checkInt(goodsData.num), isFirstReward = true})
            else
                local nums = rewardsDict[checkInt(goodsData.goodsId)] or 0
                rewardsDict[checkInt(goodsData.goodsId)] = nums + checkInt(goodsData.num)
            end
        end
    end

    -- 装备奖励
    local equipmentList = {}
    for goodId, num in pairs(rewardsDict) do
        local goodType = GoodsUtils.GetIdType(goodId)
        if num > 0 and goodType == Constants.IDType.Equipment then
            table.insert(equipmentList, {goodsId = goodId, num = num, isFirstReward = false})
        end
    end

    table.inPlaceBubbleSort(equipmentList, function ( good1, good2 )
        return checkInt(good1.goodsId) > checkInt(good2.goodsId)
    end)
    
    -- 其他奖励
    local otherList = {}
    for goodId, num in pairs(rewardsDict) do
        local goodType = GoodsUtils.GetIdType(goodId)
        if num > 0 and goodType ~= Constants.IDType.Equipment then
            table.insert(otherList, {goodsId = goodId, num = num, isFirstReward = false})
        end
    end

    table.inPlaceBubbleSort(otherList, function (good1, good2)
        return checkInt(good1.goodsId) > checkInt(good2.goodsId)
    end)

    self.rewardList = {}
    table.link(self.rewardList, firstList)
    table.link(self.rewardList, equipmentList)
    table.link(self.rewardList, otherList)
end

---刷新奖励列表
function UIBattleEndContinuousFightSummaryDialog:RefreshRewardsList(maxNum)
    if not self.LoopGridView.IsListViewInit then
        self.LoopGridView:InitGridView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopGridView, maxNum)
    end
end

function UIBattleEndContinuousFightSummaryDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local idx = index + 1
    local cell = loopListView:NewListViewItem("Cell")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
    end
    local goodsNode = cell.transform:Find('GoodNode')
    local data = self.rewardList[idx]
    -- print("[连续作战] 滚动条", idx)
    if data then
        CfUtils.RefeshGoodGo2(goodsNode, data.goodsId, data.num)
        if data.isFirstReward then
            local LB_GoodsNode = GetLuaBehaviour(goodsNode.gameObject, "Game.Behaviours.GoodNodeMB")
            LB_GoodsNode.Env:SetBonusText(localize("首通奖励"), 3)
        end
    end
    return cell
end

--- 刷新固定奖励
function UIBattleEndContinuousFightSummaryDialog:RefreshExtraRewardsList()
    local rewardsList = teamComponent:GetContinueFightExtraRewards()
    if table.count(rewardsList) == 0 then
        KTool.SetActive(self.Txt_ExtraRewards.transform.parent, false)
    else
        local rewardsDict = {}
        for i, onceRewards in ipairs(rewardsList) do
            for j, goodsData in ipairs(onceRewards) do
                local nums = rewardsDict[checkInt(goodsData.goodsId)] or 0
                rewardsDict[checkInt(goodsData.goodsId)] = nums + checkInt(goodsData.num)
            end
        end
        
        for goodId, num in pairs(rewardsDict) do
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodId)
            self.Img_ExtraRewards:LoadSprite(vo.photoPath)
            self.Txt_ExtraRewards.text = string.format("x%d", checkInt(num))
        end
    end
end

return UIBattleEndContinuousFightSummaryDialog
